/**
 * Client-side analytics helper.
 *
 * Returns the PostHog anonymous distinct id — a random UUID generated by
 * posthog-js and stored in the visitor's browser, created ONLY after the
 * consent banner was accepted (the whole PostHog client is consent-gated;
 * see src/components/consent-gate.tsx). It is not an account id, not an
 * email, and contains no personal data.
 *
 * Purpose: attaching it to server-side conversion captures (subscribe) lets
 * PostHog build person-level funnels — which pages precede a signup — while
 * the server events themselves still carry no email/name/message content.
 *
 * Safe by design: returns null whenever PostHog is not loaded (consent
 * declined, DNT respected, blocked, or SSR). Analytics must never break the
 * form.
 */

interface PosthogWindow {
  __loaded?: boolean;
  get_distinct_id?: () => string;
}

export function analyticsDistinctId(): string | undefined {
  if (typeof window === "undefined") return undefined;
  try {
    const ph = (window as unknown as { posthog?: PosthogWindow }).posthog;
    if (ph && ph.__loaded && typeof ph.get_distinct_id === "function") {
      const id = ph.get_distinct_id();
      // Sanity bound: real posthog ids are UUID-ish or numeric strings.
      if (typeof id === "string" && id.length >= 8 && id.length <= 200) {
        return id;
      }
    }
  } catch {
    /* ignore — form flow continues without analytics */
  }
  return undefined;
}
